CREATE TABLE system_operations(operation_id TEXT PRIMARY KEY,request_id TEXT NOT NULL,trace_id TEXT NOT NULL,actor_key TEXT,realm TEXT NOT NULL,organization_id TEXT,project_id TEXT,environment_id TEXT,base_revision INTEGER,request_key TEXT,fingerprint TEXT,policy_version INTEGER NOT NULL,operation TEXT NOT NULL,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,error_code TEXT);
CREATE INDEX system_operation_scope ON system_operations(organization_id,project_id,environment_id,started_at DESC);
CREATE TABLE system_work_stage_budgets(work_id TEXT NOT NULL REFERENCES work_items(id),phase TEXT NOT NULL,budget_ms INTEGER NOT NULL,deadline INTEGER NOT NULL,status TEXT NOT NULL,started_at INTEGER NOT NULL,finished_at INTEGER,PRIMARY KEY(work_id,phase));
CREATE TABLE system_alert_policies(scope_key TEXT NOT NULL,id TEXT NOT NULL,metric TEXT NOT NULL,threshold INTEGER NOT NULL CHECK(threshold>=0),window_ms INTEGER NOT NULL CHECK(window_ms BETWEEN 1000 AND 86400000),revision INTEGER NOT NULL,enabled INTEGER NOT NULL CHECK(enabled IN(0,1)),PRIMARY KEY(scope_key,id));
CREATE TABLE system_storage_migrations(id TEXT PRIMARY KEY,scope TEXT NOT NULL CHECK(json_valid(scope)),state TEXT NOT NULL,body TEXT NOT NULL CHECK(json_valid(body)),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
